func LoginHandler(service *AuthService) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        var req LoginRequest
        if err := decodeJSON(r.Body, &req); err != nil {
            writeError(w, NewBadRequest("invalid login body"))
            return
        }
        session, err := service.Login(r.Context(), req.Email, req.Password)
        if err != nil {
            writeError(w, err)
            return
        }
        writeJSON(w, http.StatusOK, session)
    }
}

type AuthService struct {
    users    *UserRepository
    sessions *SessionSigner
}

func (s *AuthService) Login(ctx context.Context, email, password string) (*Session, error) {
    user, err := s.users.FindByEmail(ctx, email)
    if err != nil {
        return nil, NewUnauthorized("invalid credentials")
    }
    if !ValidatePassword(password, user.PasswordHash) {
        return nil, NewUnauthorized("invalid credentials")
    }
    return s.sessions.IssueSession(user.ID)
}

func ValidatePassword(password, storedHash string) bool {
    return subtle.ConstantTimeCompare(hash(password), []byte(storedHash)) == 1
}

type UserRepository struct {
    db *sql.DB
}

func (r *UserRepository) FindByEmail(ctx context.Context, email string) (*User, error) {
    row := r.db.QueryRowContext(ctx, `SELECT id, email, password_hash FROM users WHERE email = ?`, email)
    var user User
    if err := row.Scan(&user.ID, &user.Email, &user.PasswordHash); err != nil {
        return nil, err
    }
    return &user, nil
}

func RequireAuth(verifier *SessionVerifier, next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        token := bearerToken(r.Header.Get("Authorization"))
        claims, err := verifier.Verify(token)
        if err != nil {
            writeError(w, NewUnauthorized("missing or invalid session"))
            return
        }
        ctx := context.WithValue(r.Context(), userIDKey{}, claims.UserID)
        next.ServeHTTP(w, r.WithContext(ctx))
    })
}

func NewRouter(auth *AuthService, orders *OrderService, verifier *SessionVerifier) http.Handler {
    mux := http.NewServeMux()
    mux.Handle("POST /login", LoginHandler(auth))
    mux.Handle("POST /orders", RequireAuth(verifier, OrderHandler(orders)))
    mux.Handle("GET /orders/{id}", RequireAuth(verifier, OrderStatusHandler(orders)))
    return requestLogger(recoverPanics(mux))
}

type OrderService struct {
    inventory *InventoryService
    payments  *PaymentClient
    shipping  *ShippingService
    orders    *OrderRepository
}

func (s *OrderService) PlaceOrder(ctx context.Context, req OrderRequest) (*Order, error) {
    reservation, err := s.inventory.Reserve(ctx, req.Items)
    if err != nil {
        return nil, err
    }
    charge, err := s.payments.Charge(ctx, req.PaymentToken, reservation.Total)
    if err != nil {
        s.inventory.Release(ctx, reservation.ID)
        return nil, err
    }
    order := NewOrder(req.CustomerID, reservation, charge)
    if err := s.orders.Save(ctx, order); err != nil {
        return nil, err
    }
    return order, s.shipping.CreateShipment(ctx, order)
}

type OrderRepository struct {
    db *sql.DB
}

func (r *OrderRepository) Save(ctx context.Context, order *Order) error {
    _, err := r.db.ExecContext(ctx, `INSERT INTO orders (id, customer_id, total, status) VALUES (?, ?, ?, ?)`, order.ID, order.CustomerID, order.Total, order.Status)
    return err
}

func (s *InventoryService) Reserve(ctx context.Context, items []LineItem) (*Reservation, error) {
    for _, item := range items {
        if item.Quantity <= 0 {
            return nil, NewBadRequest("quantity must be positive")
        }
        if !s.stock.HasAvailable(ctx, item.SKU, item.Quantity) {
            return nil, NewConflict("insufficient inventory")
        }
    }
    return s.stock.CreateReservation(ctx, items)
}

type PaymentClient struct {
    endpoint string
    http     *http.Client
}

func (c *PaymentClient) Charge(ctx context.Context, token string, amount Money) (*Charge, error) {
    if token == "" {
        return nil, NewBadRequest("payment token is required")
    }
    req := newChargeRequest(token, amount)
    resp, err := c.http.Do(req.WithContext(ctx))
    if err != nil {
        return nil, err
    }
    return decodeCharge(resp)
}

func (s *ShippingService) CreateShipment(ctx context.Context, order *Order) error {
    label, err := s.carrier.BuyLabel(ctx, order.ShippingAddress, order.Items)
    if err != nil {
        return err
    }
    order.Status = StatusReadyToShip
    order.ShipmentID = label.ID
    return nil
}

func LoadConfig(path string) (*Config, error) {
    data, err := os.ReadFile(path)
    if err != nil {
        return nil, err
    }
    var cfg Config
    if err := json.Unmarshal(data, &cfg); err != nil {
        return nil, err
    }
    if cfg.DatabaseURL == "" || cfg.PaymentEndpoint == "" {
        return nil, NewBadRequest("missing required configuration")
    }
    return &cfg, nil
}

type AppError struct {
    Code    string
    Message string
    Status  int
}

func NewBadRequest(message string) *AppError {
    return &AppError{Code: "bad_request", Message: message, Status: http.StatusBadRequest}
}

func NewUnauthorized(message string) *AppError {
    return &AppError{Code: "unauthorized", Message: message, Status: http.StatusUnauthorized}
}

func NewConflict(message string) *AppError {
    return &AppError{Code: "conflict", Message: message, Status: http.StatusConflict}
}
